 const rows=data?.prices||[],highest=rows.length?rows.reduce((a,b)=>Number(b.Price)>Number(a.Price)?b:a):null,lowest=rows.length?rows.reduce((a,b)=>Number(b.Price)<Number(a.Price)?b:a):null
